-- Only disposable local fixtures; never run against a network database.
do $$begin if current_database()<>'byus_clean' or inet_server_addr() is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.wallet_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.wallet_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare owner uuid:='e9000000-0000-4000-8000-000000000001';other uuid:='e9000000-0000-4000-8000-000000000002';a uuid:='e9000000-0000-4000-8000-000000000010';b uuid:='e9000000-0000-4000-8000-000000000011';pa uuid;pb uuid;key uuid:=extensions.gen_random_uuid();legacy_key uuid:=extensions.gen_random_uuid();source uuid;entry uuid;answer jsonb;prior jsonb;today date:=(clock_timestamp()at time zone'Asia/Seoul')::date;i integer;ad uuid;ad2 uuid;res jsonb;k2 uuid;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:group-wallet-test','wallet@example.test'),(other,'did:privy:group-wallet-other','wallet-other@example.test');
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role)values(a,'group-wallet-a','published','/fixture.webp',now(),'{creator}','creator'),(b,'group-wallet-b','published','/fixture.webp',now(),'{creator}','creator');
 insert into public.mobile_fan_economy_policies(celebrity_id,version,kind,rules,effective_at)values(a,'fixture-v1','exchange','{"free_draw":100,"support_voucher":100}',clock_timestamp())returning id into pa;
 insert into public.mobile_fan_economy_policies(celebrity_id,version,kind,rules,effective_at)values(b,'fixture-v1','exchange','{"free_draw":100,"support_voucher":100}',clock_timestamp())returning id into pb;
 perform public.mobile_fan_economy_post(owner,a,'fan_point',100,'fixture',extensions.gen_random_uuid(),pa);
 perform public.mobile_fan_economy_post(owner,b,'fan_point',200,'fixture',extensions.gen_random_uuid(),pb);
 perform public.mobile_fan_economy_post(owner,a,'paid_vote',3,'fixture',extensions.gen_random_uuid(),pa);
 perform public.mobile_fan_economy_post(owner,a,'free_vote',4,'fixture',extensions.gen_random_uuid(),pa);
 prior:=public.post_fan_ticket_entry(owner,a,'credit',2,'fixture',a,legacy_key,2);
 perform public.post_fan_ticket_entry(owner,b,'credit',3,'fixture',b,extensions.gen_random_uuid(),2);
 perform pg_temp.wallet_assert(public.get_fan_ticket_balance(owner,a)=2 and public.get_fan_ticket_balance(owner,b)=3,'disabled release retains legacy creator balances');
 perform pg_temp.wallet_error(format('select public.read_owned_group_wallet(%L)',owner),'UNAVAILABLE');
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('a',64),rewards_start_on=today;
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'fan_point')=300 and public.group_wallet_balance(owner,'ticket')=5,'legacy free balances project once without copying rows');
 perform pg_temp.wallet_assert(public.mobile_fan_economy_balance(owner,b,'fan_point')=300 and public.get_fan_ticket_balance(owner,a)=5,'legacy readers use same global free balance');
 perform pg_temp.wallet_assert(public.post_fan_ticket_entry(owner,a,'credit',2,'fixture',a,legacy_key,2)=prior||'{"replayed":true}'::jsonb,'old receipt replay preserves original creator and resulting balance');
 answer:=public.exchange_owned_group_wallet(owner,key,'group-wallet-v1','heart',1);
 perform pg_temp.wallet_assert(public.exchange_owned_group_wallet(owner,key,'group-wallet-v1','heart',1)=answer||'{"replayed":true}'::jsonb and public.group_wallet_balance(owner,'fan_point')=200 and public.group_wallet_balance(owner,'support_voucher')=1,'heart exchange atomic and replay-safe');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1)',owner,key),'REQUEST_CONFLICT');
 -- Ad-session forgery matrix. Limits below are test-only values (ttl 600s, min watch 1s, 5 issues/hour, daily cap 2).
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1)',owner,extensions.gen_random_uuid()),'AD_SESSION_REQUIRED');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),extensions.gen_random_uuid()),'AD_SESSION_INVALID');
 perform pg_temp.wallet_error(format('select public.issue_owned_group_wallet_ad_session(%L,null,5,3600,2)',owner),'AD_CONFIG_MISSING');
 perform pg_temp.wallet_error(format('select public.issue_owned_group_wallet_ad_session(%L,600,0,3600,2)',owner),'AD_CONFIG_MISSING');
 perform pg_temp.wallet_error(format('select public.issue_owned_group_wallet_ad_session(%L,600,5,3600,null)',owner),'AD_CONFIG_MISSING');
 perform pg_temp.wallet_assert(not exists(select 1 from public.group_wallet_ad_sessions where app_user_id=owner),'missing config issues no session');
 ad:=(public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2)->>'sessionId')::uuid;
 ad2:=(public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2)->>'sessionId')::uuid;
 perform pg_temp.wallet_assert(ad2<>ad and(select voided_at is not null and void_reason='replaced' from public.group_wallet_ad_sessions where id=ad)and(select count(*) from public.group_wallet_ad_sessions where app_user_id=owner and consumed_at is null and voided_at is null)=1,'one unused session per account; reissue replaces');
 ad:=(select id from public.group_wallet_ad_sessions where app_user_id=owner and voided_at is null);
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'AD_SESSION_INVALID');
 perform pg_temp.wallet_error(format('select public.report_owned_group_wallet_ad_session(%L,%L,''granted'',1)',owner,ad),'AD_SESSION_INVALID');
 perform pg_temp.wallet_error(format('select public.report_owned_group_wallet_ad_session(%L,%L,''shown'',null)',owner,ad),'AD_CONFIG_MISSING');
 perform pg_temp.wallet_error(format('select public.report_owned_group_wallet_ad_session(%L,%L,''shown'',1)',other,ad),'AD_SESSION_INVALID');
 perform public.report_owned_group_wallet_ad_session(owner,ad,'shown',1);
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'AD_SESSION_INVALID');
 res:=public.report_owned_group_wallet_ad_session(owner,ad,'granted',1);
 perform pg_temp.wallet_assert(res->>'status'='invalid'and(select void_reason='too_fast' from public.group_wallet_ad_sessions where id=ad),'granted below minimum viewing interval is invalid and voids the session');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'AD_SESSION_INVALID');
 ad:=(public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2)->>'sessionId')::uuid;
 perform public.report_owned_group_wallet_ad_session(owner,ad,'shown',1);perform pg_sleep(1.2);
 perform pg_temp.wallet_assert(public.report_owned_group_wallet_ad_session(owner,ad,'granted',1)->>'status'='granted','granted after minimum interval is accepted');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',other,extensions.gen_random_uuid(),ad),'AD_SESSION_INVALID');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',2,%L,2)',owner,extensions.gen_random_uuid(),ad),'GROUP_WALLET_INVALID');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'GROUP_WALLET_INVALID');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,null)',owner,extensions.gen_random_uuid(),ad),'AD_CONFIG_MISSING');
 perform pg_temp.wallet_assert((select consumed_at is null from public.group_wallet_ad_sessions where id=ad)and public.group_wallet_balance(owner,'ticket')=5,'rejected exchanges neither consume the session nor credit tickets');
 k2:=extensions.gen_random_uuid();
 answer:=public.exchange_owned_group_wallet(owner,k2,'group-wallet-v1','ticket',1,ad,2);
 perform pg_temp.wallet_assert(answer->>'units'='1'and public.group_wallet_balance(owner,'ticket')=6 and public.group_wallet_balance(owner,'fan_point')=100 and(select consumed_request_key=k2 from public.group_wallet_ad_sessions where id=ad),'ticket exchange consumes the session and grants exactly one ticket');
 perform pg_temp.wallet_assert(public.exchange_owned_group_wallet(owner,k2,'group-wallet-v1','ticket',1,ad,2)=answer||'{"replayed":true}'::jsonb and public.group_wallet_balance(owner,'ticket')=6,'idempotent retry does not add tickets');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'AD_SESSION_INVALID');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,k2,extensions.gen_random_uuid()),'REQUEST_CONFLICT');
 perform pg_temp.wallet_error(format('select public.issue_owned_group_wallet_ad_session(%L,600,5,3600,1)',owner),'AD_DAILY_LIMIT');
 ad:=(public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2)->>'sessionId')::uuid;
 perform public.report_owned_group_wallet_ad_session(owner,ad,'shown',1);perform pg_sleep(1.2);perform public.report_owned_group_wallet_ad_session(owner,ad,'granted',1);
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,1)',owner,extensions.gen_random_uuid(),ad),'AD_DAILY_LIMIT');
 res:=public.issue_owned_group_wallet_ad_session(owner,600,5,3600,2);
 perform pg_temp.wallet_assert(res->>'sessionId'=ad::text and res->>'status'='granted'and public.group_wallet_balance(owner,'ticket')=6,'daily cap rejection keeps tickets; a watched unspent session is handed back');
 perform pg_temp.wallet_assert((select count(*) from public.group_wallet_receipts where app_user_id=owner and operation='exchange'and input->>'target'='ticket')=1 and(select count(*) from public.group_wallet_ad_sessions where app_user_id=owner and consumed_at is not null)=1,'receipts and consumed sessions reconcile');
 perform public.post_fan_ticket_entry(owner,a,'debit',-3,'fixture_debit',extensions.gen_random_uuid(),extensions.gen_random_uuid(),2);
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'ticket')=3 and public.get_fan_ticket_balance(owner,b)=3,'legacy debit consumes same tickets as global exchange');
 perform pg_temp.wallet_error(format('select public.group_wallet_post(%L,''ticket'',-4,''group_capsule'',%L)',owner,extensions.gen_random_uuid()),'INSUFFICIENT_BALANCE');
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'ticket')=3,'failed debit does not spend');
 perform pg_temp.wallet_assert(public.mobile_fan_economy_balance(owner,a,'paid_vote')=3 and public.mobile_fan_economy_balance(owner,b,'paid_vote')=0 and public.mobile_fan_economy_balance(owner,a,'free_vote')=4,'paid rights and vote assets retain creator scope');
 for i in 1..6 loop
  source:=extensions.gen_random_uuid();entry:=public.group_wallet_post(owner,'fan_point',10,'group_check_in',source);
  insert into public.group_wallet_attendance values(owner,today-7+i,i,10,entry);
 end loop;
 key:=extensions.gen_random_uuid();answer:=public.check_in_owned_group_wallet(owner,key);
 perform pg_temp.wallet_assert(answer->>'pointsAwarded'='30'and answer->>'streak'='7','seventh consecutive day awards 10 plus 20');
 perform public.check_in_owned_group_wallet(owner,key);perform public.check_in_owned_group_wallet(owner,extensions.gen_random_uuid());
 perform pg_temp.wallet_assert((select count(*)from public.group_wallet_attendance where app_user_id=owner and attendance_date=today)=1 and public.group_wallet_balance(owner,'fan_point')=190,'same date and key award exactly once');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(other,key)->>'status'='unknown','receipt ownership isolated');
 perform pg_temp.wallet_assert(not exists(select 1 from public.community_stamps where app_user_id=owner)and not exists(select 1 from public.fan_score_ledger where app_user_id=owner),'global points do not mint creator stamps or change XP');
 key:=extensions.gen_random_uuid();answer:=public.send_owned_group_wallet_support(owner,key,'group-wallet-v1','group-wallet-b',1);
 perform pg_temp.wallet_assert(public.send_owned_group_wallet_support(owner,key,'group-wallet-v1','group-wallet-b',1)=answer||'{"replayed":true}'::jsonb and public.group_wallet_balance(owner,'support_voucher')=0 and(select count(*)from public.mobile_fan_support_contributions where app_user_id=owner and request_key=key)=1,'global heart send preserves original contribution FK and replays once');
 perform pg_temp.wallet_assert(not exists(select 1 from public.mobile_fan_economy_policies where celebrity_id=b and version='group-wallet-support-v1'and retired_at is null),'global send audit policy never replaces active creator policy');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(owner,legacy_key)->>'status'='legacy','old transaction is not mislabeled unknown');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1)',owner,legacy_key),'REQUEST_CONFLICT');
 source:=extensions.gen_random_uuid();insert into public.mobile_fan_economy_cancellations values(owner,source,'exchange','{}',clock_timestamp());
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1)',owner,source),'REQUEST_CONFLICT');
 source:=extensions.gen_random_uuid();entry:=public.group_wallet_post(other,'fan_point',130,'group_check_in',source);
 insert into public.group_wallet_attendance values(other,today-1,13,10,entry);
 answer:=public.check_in_owned_group_wallet(other,extensions.gen_random_uuid());
 perform pg_temp.wallet_assert(answer->>'pointsAwarded'='30'and answer->>'streak'='14','every seventh day awards again, not once per account');
 perform pg_temp.wallet_assert(public.award_mobile_fan_activity(owner,a,'checkin',today::text)->>'status'='not_eligible'and public.award_mobile_fan_activity(owner,b,'checkin',today::text)->>'status'='not_eligible'and public.group_wallet_balance(owner,'fan_point')=190,'legacy creator check-ins cannot duplicate global daily point producer');
 perform public.issue_owned_group_wallet_ad_session(other,600,2,3600,5);perform public.issue_owned_group_wallet_ad_session(other,600,2,3600,5);
 perform pg_temp.wallet_error(format('select public.issue_owned_group_wallet_ad_session(%L,600,2,3600,5)',other),'AD_RATE_LIMITED');
 perform pg_temp.wallet_assert((select count(*) from public.group_wallet_ad_sessions where app_user_id=other)=2,'issue rate limit refuses further sessions inside the window');
 key:=extensions.gen_random_uuid();perform public.check_in_owned_group_wallet(owner,key);
 update public.group_wallet_release set write_fenced=true;
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1,%L,2)',owner,extensions.gen_random_uuid(),ad),'WRITE_FENCED');
 perform pg_temp.wallet_error(format('select public.post_fan_ticket_entry(%L,%L,''credit'',1,''fenced'',%L,%L,2)',owner,a,extensions.gen_random_uuid(),extensions.gen_random_uuid()),'WRITE_FENCED');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(owner,key)->>'status'='committed','fence preserves committed request recovery');
 perform pg_temp.wallet_assert(not has_table_privilege('service_role','public.group_wallet_release','UPDATE')and not has_function_privilege('authenticated','public.exchange_owned_group_wallet(uuid,uuid,text,text,integer,uuid,integer)','EXECUTE')and not has_function_privilege('anon','public.issue_owned_group_wallet_ad_session(uuid,integer,integer,integer,integer)','EXECUTE')and not has_table_privilege('service_role','public.group_wallet_ad_sessions','UPDATE')and has_function_privilege('service_role','public.report_owned_group_wallet_ad_session(uuid,uuid,text,integer)','EXECUTE'),'activation and currency writer not client-writable');
end $$;
rollback;
